    }
    if hovered.as_deref() == Some(id) {
        return Some(([0.35, 0.75, 1.0, 0.9], VERTEX_HOVER_SCALE));
    }
    if selected.contains(id) {
        return Some(([0.35, 0.75, 1.0, 1.0], VERTEX_SELECT_SCALE));
    }
    None
}

