    /// mode's, else the 45° `parseCameraState` default.
    fn fov_degrees(&self) -> f64 {
        self.projection.map(|spec| f64::from(ui_wgpu::wgpu::projection_spec_fov_degrees(spec))).or(self.fov).unwrap_or(45.0)
    }
