    let mut input = ui_wgpu::wgpu::InputState::<ActionDescriptor>::default();
    for (generation, reason) in [(4, WorldCancelReason::Blur), (5, WorldCancelReason::CaptureLost)] {
        state.paint_stroke_active = true;
