    let sun = environment_light_dir(&state.environment);
    let expected_sun = expect["sunDirection"].as_array().expect("sun");
    for axis in 0..3 {
        assert!((f64::from(sun[axis]) - expected_sun[axis].as_f64().expect("axis")).abs() < 1.0e-5, "sun axis {axis}: {sun:?}");
    }
}

