/// 🔒️ Live commands retain admitted start targets while current picking changes and refuse a different surface owner.
#[test]
fn world_live_captured_authority_retains_start_ids_and_refuses_replaced_owner() {
    let law: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/🎯️captured-gesture-authority/🔣️.json")).unwrap();
    let fixture: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/🎯️component-selection-merges/🔣️.json")).unwrap();
    let row = &fixture["gumball"];
    let maximum = law["maximumTurns"].as_u64().unwrap() as usize;
    for case in law["cases"].as_array().unwrap() {
        let targets: Vec<String> = row["ids"].as_array().unwrap().iter().map(|index| fixture["targets"][index.as_u64().unwrap() as usize].as_str().unwrap().to_string()).collect();
        let object = fixture["objects"][row["object"].as_u64().unwrap() as usize].as_str().unwrap();
        let mut mesh = fixture["mesh"].clone();
        mesh["componentReferences"] = serde_json::json!({"face":[fixture["source"]["label"]]});
        let mut scene = scene_with_selection_and_domain("{}", Some(("geometry", "object")));
        let world = scene.world_3d.as_mut().unwrap();
        world.meshes_json = serde_json::json!([{"id":"analytic","data":mesh}]).to_string();
        world.instances_json = serde_json::json!([{"id":object,"meshId":"analytic","componentSource":{"handle":fixture["source"]["handle"],"revision":fixture["source"]["revision"]}}]).to_string();
        world.camera_json = row["liveRefresh"]["camera"].to_string();
        world.selection_json = serde_json::json!({"ids":[object],"granularity":row["mode"],"gumballSelectionIds":targets,"gumballTarget":row["pivot"],"transformMode":"move","gumballLiveDispatch":true}).to_string();
        let mut state = World3dState::new("surface".into(), "controller".into());
        drive_scene_bridge(&mut state, &scene, Rect::new(0.0, 0.0, 400.0, 400.0));
        set_world3d_declared_actions(&mut state, &[TRANSLATE_SELECTION_ACTION_ID.into()]);
        let mut registry = WorldInteractionRegistryBuildCursor::new(state.interaction_revision);
        let mut ready = false;
        for _ in 0..maximum {
            if with_world_step_context(1, |context| registry.step(&mut state, context)) == WorldInteractionStep::Complete { ready = true; break; }
        }
        assert!(ready, "the original registry completes under one-unit grants");
        let mut pick = WorldGumballPickCursor::new(&state, 12, row["pointer"][0].as_f64().unwrap() as f32, row["pointer"][1].as_f64().unwrap() as f32);
        assert_eq!(with_world_step_context(0, |context| pick.step(&state, 12, context)), WorldInteractionStep::Pending);
        assert_eq!(pick.capture.as_ref().unwrap().byte_len, 0);
        ready = false;
        for _ in 0..maximum {
            if with_world_step_context(1, |context| pick.step(&state, 12, context)) == WorldInteractionStep::Complete { ready = true; break; }
        }
        assert!(ready, "the original live pick copies its admitted target bytes under one-unit grants");
        let mut gesture = pick.finish(&state, 12).unwrap_or_else(|_| panic!("current captured owner")).expect("actual component gumball");
        assert_eq!(gesture.captured.as_ref().unwrap().byte_len, gesture.selected_bytes);
        assert!(gesture.live);
        match case["scenario"].as_str().unwrap() {
            "view-revision" => advance_world3d_view_revision(&mut state),
            "selection-replacement" => sync_world3d_scene_selection(&mut state, &serde_json::json!({"ids":[object],"granularity":row["mode"],"gumballSelectionIds":[law["replacementId"]],"transformMode":"move","gumballLiveDispatch":true}).to_string()),
            "surface-replacement" => state.surface_id = law["replacementOwner"].as_str().unwrap().into(),
            "controller-replacement" => state.controller_id = law["replacementOwner"].as_str().unwrap().into(),
            _ => unreachable!(),
        }
        let accepted = case["accepted"].as_bool().unwrap();
        assert_eq!(gesture.current(&state), accepted);
        assert_eq!(gesture.begin_update(13, row["movedPointer"][0].as_f64().unwrap() as f32, row["movedPointer"][1].as_f64().unwrap() as f32), WorldInteractionStep::Pending);
        let mut outcome = WorldInteractionStep::Pending;
        for _ in 0..maximum {
            outcome = gesture.update_step(&state);
            if outcome != WorldInteractionStep::Pending { break; }
        }
        assert_eq!(outcome, if accepted { WorldInteractionStep::Complete } else { WorldInteractionStep::Stale });
        if accepted {
            for (index, target) in targets.iter().enumerate() { assert_eq!(gesture.target_text(&state, index), Some(target.as_str())); }
            let action = world_gumball_publish(&state, gesture.publication((Vec3::new(1.0, 0.0, 0.0), 0.0, Vec3::new(1.0, 1.0, 1.0))), WorldGumballPhase::Stream).expect("captured command");
            assert_eq!(action.args.as_ref().unwrap().get("ids").unwrap().as_array().unwrap().iter().map(|value| value.as_str().unwrap()).collect::<Vec<_>>(), targets.iter().map(String::as_str).collect::<Vec<_>>());
        } else {
            assert_eq!(gesture.target_text(&state, 0), None);
            let mut input = ui_wgpu::wgpu::InputState::<ActionDescriptor>::default();
            let mut job = WorldGumballCommitJob::new(13, gesture.publication(world_gumball_identity_motion()), WorldGumballPhase::Commit);
            assert_eq!(with_world_step_context(1, |context| job.step(&state, 13, &mut input, context)).unwrap(), WorldInteractionStep::Stale);
            ready = false;
            for _ in 0..maximum { if job.close_step(&mut input) { ready = true; break; } }
            assert!(ready, "the rejected captured publication retires every owner");
            assert!(take_actions(&mut input).is_empty());
            while !input.close_step().unwrap() {}
            assert!(input.terminal_is_empty());
        }
        ready = false;
        for _ in 0..maximum { if gesture.close_step() { ready = true; break; } }
        assert!(ready, "the captured gesture retires one target per turn");
        assert_eq!(gesture.selected_len, 0);
        assert_eq!(gesture.selected_bytes, 0);
        assert!(gesture.captured.is_none());
        retire_bridged_surface(&mut state);
    }
    println!("[DEBUG] capturedLiveCommandAuthority exactStartIds=true changedViewAndSelection=true surfaceAndControllerRefused=true byteCopyPerFuel=1 boundedOwnerRetirement=true");
}

/// 🎯️ The owning World native target retains the same neutral Three ray depths consumed by picking.
#[test]
fn native_wire_ray_depth_matches_neutral_three_closest_pair() {
    let fixture: serde_json::Value = serde_json::from_str(include_str!("../../../../../../../🔨️modules/🖱️ui/🎬️scene/🧫️fixtures/🎯️ray-closest-depth/🔣️.json")).unwrap();
    for row in fixture["cases"].as_array().unwrap() {
        let vector = |key: &str| Vec3::new(row[key][0].as_f64().unwrap() as f32, row[key][1].as_f64().unwrap() as f32, row[key][2].as_f64().unwrap() as f32);
        let origin = vector("origin");
        let direction = vector("direction").normalize();
        let (ray, segment) = ui_wgpu::wgpu::ray_segment_closest_pair(origin, direction, vector("a"), vector("b")).expect("finite nondegenerate source pair");
        let distance = ray.sub(segment).length();
        assert!((f64::from(distance) - row["expect"]["distance"].as_f64().unwrap()).abs() < 1e-4, "{}: {distance}", row["id"]);
        let depth = ray.sub(origin).dot(direction);
        assert!(depth >= 0.0, "{}: forward ray", row["id"]);
        if row["expect"]["uniqueDepth"].as_bool().unwrap() {
            assert!((f64::from(depth) - row["expect"]["rayDepth"].as_f64().unwrap()).abs() < 1e-4, "{}: {depth}", row["id"]);
        }
        assert!((ray_segment_distance(origin, direction, vector("a"), vector("b")).unwrap() - distance).abs() < 1e-6);
    }
    assert!(ui_wgpu::wgpu::ray_segment_closest_pair(Vec3::ZERO, Vec3::ZERO, Vec3::ZERO, Vec3::new(1.0, 0.0, 0.0)).is_none());
    assert!(ui_wgpu::wgpu::ray_segment_closest_pair(Vec3::ZERO, Vec3::new(1.0, 0.0, 0.0), Vec3::ZERO, Vec3::ZERO).is_none());
    assert!(ui_wgpu::wgpu::ray_segment_closest_pair(Vec3::new(f32::NAN, 0.0, 0.0), Vec3::new(1.0, 0.0, 0.0), Vec3::ZERO, Vec3::new(1.0, 0.0, 0.0)).is_none());
    println!("[DEBUG] nativeWireRayDepth cases=12 finiteEndpoints=true midpointDepthExcluded=true forwardRay=true independentThree=true");
}

