        "up": [0, 0, 1],
        "fov": 50,
        "zoom": 1,
        "projection": spec,
    })
    .to_string();
    let mut state = World3dState::new("surface-delivered-projection".into(), "controller".into());
    state.camera_user_moved = true;

    drive_scene_bridge(&mut state, &scene, viewport);
