    pub(super) fn validate_engine_renderer_allocation(&self, admission: &RasterTextureAdmission, expected: RasterTextureWitness) -> Result<(), &'static str> {
        self.claim_stage_before_gpu_allocation(admission, expected).map(|_| ())
    }

