pub(crate) enum RasterUploadPixels<'a> {
    #[cfg(test)]
    Contiguous(&'a [u8]),
    Pages(&'a PreparedRasterPages),
    Scene(&'a crate::wgpu::raster_ownership::SceneRasterLease),
