    if !matches!(field,Mesh3dField::Colors | Mesh3dField::Tangents) || !value.iter().all(|value| value.is_finite()) {
        return Err(Mesh3dFault::Schema);
    }
    let mut bytes = [0; 16];
    for (index, value) in value.into_iter().enumerate() {
