impl SceneMaterialKind3d {
    pub fn texture_key(&self) -> Option<&str> {
        match self {
            Self::Painted { texture_key } => Some(texture_key),
            Self::Authored(material) => material.base_color_texture.as_deref(),
            Self::Standard | Self::Celebration { .. } => None,
