    let rotated = rotate_vector(vec3_new_m(1.0, 0.0, 0.0), vec3_new_m(0.0, 0.0, 1.0), std::f32::consts::FRAC_PI_2);
    assert!((rotated.x - 0.0).abs() < 1e-4, "x={}", rotated.x);
