/// 🎯️ Resolves both minimizing points on a forward ray and a finite nondegenerate segment.
pub fn ray_segment_closest_pair(origin: Vec3, dir: Vec3, a: Vec3, b: Vec3) -> Option<(Vec3, Vec3)> {
    if ![origin.x, origin.y, origin.z, dir.x, dir.y, dir.z, a.x, a.y, a.z, b.x, b.y, b.z].into_iter().all(f32::is_finite) {
        return None;
    }
    let ab = b.sub_m(a);
    let len_sq = ab.dot_m(ab);
    let dir_sq = dir.dot_m(dir);
    if len_sq <= 0.0 || dir_sq <= 0.0 || !len_sq.is_finite() || !dir_sq.is_finite() {
        return None;
    }
    let offset = origin.sub_m(a);
    let along_ray = offset.dot_m(dir);
    let along_segment = offset.dot_m(ab);
    let directions = dir.dot_m(ab);
    let mut best: Option<(f32, Vec3, Vec3)> = None;
    let mut consider = |ray: f32, segment: f32| {
        let ray_point = origin.add_m(dir.scale_m(ray));
        let segment_point = a.add_m(ab.scale_m(segment));
        let gap = ray_point.sub_m(segment_point);
        let squared = gap.dot_m(gap);
        if squared.is_finite() && best.is_none_or(|(distance, _, _)| squared < distance) {
            best = Some((squared, ray_point, segment_point));
        }
    };
    consider((-along_ray / dir_sq).max(0.0), 0.0);
    consider(((directions - along_ray) / dir_sq).max(0.0), 1.0);
    consider(0.0, (along_segment / len_sq).clamp(0.0, 1.0));
    let cross = dir.cross_m(ab);
    let denominator = cross.dot_m(cross);
    if denominator > 0.0 {
        let ray = (directions * along_segment - len_sq * along_ray) / denominator;
        let segment = (dir_sq * along_segment - directions * along_ray) / denominator;
        if ray >= 0.0 && (0.0..=1.0).contains(&segment) {
            consider(ray, segment);
        }
    }
    best.map(|(_, ray, segment)| (ray, segment))
}

/// 🎯️ Measures the perpendicular gap using the same finite forward closest pair.
pub fn ray_segment_distance(origin: Vec3, dir: Vec3, a: Vec3, b: Vec3) -> Option<f32> {
    ray_segment_closest_pair(origin, dir, a, b).map(|(ray, segment)| ray.sub_m(segment).length_m())
}

