/// 🎯️ Finite ray hit depths retain endpoints instead of inventing the full edge midpoint's depth.
#[test]
fn ray_segment_closest_pair_matches_neutral_three_depth_cases() {
    let fixture: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/🎯️ray-closest-depth/🔣️.json")).unwrap();
    for row in fixture["cases"].as_array().unwrap() {
        let vector = |key: &str| vec3_new_m(row[key][0].as_f64().unwrap() as f32, row[key][1].as_f64().unwrap() as f32, row[key][2].as_f64().unwrap() as f32);
        let origin = vector("origin");
        let direction = vector("direction").normalize_m();
        let (ray, segment) = ray_segment_closest_pair(origin, direction, vector("a"), vector("b")).expect("finite nondegenerate source pair");
        let distance = ray.sub_m(segment).length_m();
        assert!((f64::from(distance) - row["expect"]["distance"].as_f64().unwrap()).abs() < 1e-4, "{}: {distance}", row["id"]);
        let depth = ray.sub_m(origin).dot_m(direction);
        assert!(depth >= 0.0, "{}: forward ray", row["id"]);
        if row["expect"]["uniqueDepth"].as_bool().unwrap() {
            assert!((f64::from(depth) - row["expect"]["rayDepth"].as_f64().unwrap()).abs() < 1e-4, "{}: {depth}", row["id"]);
        }
        assert!((ray_segment_distance(origin, direction, vector("a"), vector("b")).unwrap() - distance).abs() < 1e-6);
    }
    assert!(ray_segment_closest_pair(Vec3::ZERO, Vec3::ZERO, Vec3::ZERO, vec3_new_m(1.0, 0.0, 0.0)).is_none());
    assert!(ray_segment_closest_pair(Vec3::ZERO, vec3_new_m(1.0, 0.0, 0.0), Vec3::ZERO, Vec3::ZERO).is_none());
    assert!(ray_segment_closest_pair(vec3_new_m(f32::NAN, 0.0, 0.0), vec3_new_m(1.0, 0.0, 0.0), Vec3::ZERO, vec3_new_m(1.0, 0.0, 0.0)).is_none());
    println!("[DEBUG] closestRayDepth cases=12 finiteEndpoints=true midpointDepthExcluded=true forwardRay=true independentThree=true");
}

